def zero_components(rows):
    R,C=len(rows),len(rows[0]); seen=set(); comps=[]
    for r in range(R):
      for c in range(C):
        if rows[r][c]!=0 or (r,c) in seen: continue
        st=[(r,c)]; seen.add((r,c)); comp=[]
        while st:
          x,y=st.pop(); comp.append((x,y))
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if 0<=nx<R and 0<=ny<C and rows[nx][ny]==0 and (nx,ny) not in seen:
              seen.add((nx,ny)); st.append((nx,ny))
        comps.append(comp)
    return comps
