def components_for_value(rows,val):
 R,C=len(rows),len(rows[0]); seen=set(); comps=[]; labels={}
 for r in range(R):
  for c in range(C):
   if rows[r][c]!=val or (r,c) in seen: continue
   i=len(comps); st=[(r,c)]; seen.add((r,c)); a=[]
   while st:
    x,y=st.pop(); a.append((x,y)); labels[(x,y)]=i
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<R and 0<=ny<C and rows[nx][ny]==val and (nx,ny) not in seen: seen.add((nx,ny));st.append((nx,ny))
   comps.append(a)
 return comps,labels

def adjacency(rows):
 zc=zero_components(rows); fc,fl=components_for_value(rows,5)
 for i,z in enumerate(zc):
  adj=set()
  for r,c in z:
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    p=(r+dr,c+dc)
    if p in fl:adj.add(fl[p])
  print(i, len(z), 'adj5 comps',adj)
